import java.io.*;
import java.util.*;

public class E {
    void solver() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] line1 = reader.readLine().split(" ");
        long n = Long.parseLong(line1[0]);
        String[] line2 = reader.readLine().split(" ");
        long[] ar = new long[3];
        ar[0] = Long.parseLong(line2[0]);
        ar[1] = Long.parseLong(line2[1]);
        ar[2] = Long.parseLong(line2[2]);
        String[] line3 = reader.readLine().split(" ");
        long[] br = new long[3];
        br[0] = Long.parseLong(line3[0]);
        br[1] = Long.parseLong(line3[1]);
        br[2] = Long.parseLong(line3[2]);
        long mxWins = 0;
        long mxLosesOrDraw = 0;
        int[] idx = {0, 1, 2, 0, 1, 2};
        for (int i = 0; i < 3; i++) {
            mxWins += Math.min(ar[idx[i]], br[idx[i+1]]);
            long mxLose = Math.min(br[idx[i]], ar[idx[i+1]]);
            long mxDraw = Math.min(br[idx[i]], ar[idx[i]]);
            mxLosesOrDraw += Math.min(br[idx[i]], mxLose + mxDraw);
        }
        out.pp(n - mxLosesOrDraw, mxWins);
    }

    private static final FastWriter out = new FastWriter();
    public static void main(String[] args) throws IOException {
        new E().solver();
        out.close();
    }

    static class FastWriter {
        private static final int IO_BUFFERS = 128 * 1024;
        private final StringBuilder out;
        public FastWriter() { out = new StringBuilder(IO_BUFFERS); }
        public FastWriter p(Object object) { out.append(object); return this; }
        public FastWriter pp(Object... args) { for (Object ob : args) { out.append(ob).append(" "); } out.append("\n"); return this; }
        public void close() throws IOException { System.out.print(out); }
    }
}
